  "helpGuides.content.credits.s2.title": "免费积分",
  "helpGuides.content.credits.s3.body": "积分包可在“积分”页面通过 Stripe 购买。购买的积分永不过期。",
  "helpGuides.content.credits.s3.title": "购买积分",
  "helpGuides.content.credits.s4.body": "如果生成失败，积分会自动退回你的余额。素材库会显示失败的生成及其退款。",
  "helpGuides.content.credits.s4.title": "失败时",
  "helpGuides.content.credits.s5.body": "一个账户每分钟最多可发起 10 次生成。超出部分会被拒绝，且不会向您扣费。",
  "helpGuides.content.credits.s5.title": "限制",
  "helpGuides.content.credits.summary": "一个余额，价格事先可见，自动退款。",
  "helpGuides.content.credits.title": "积分与退款如何运作",
  "helpGuides.content.first-generation.l1": "打开工作室",
  "helpGuides.content.first-generation.l2": "查看所有价格",
  "helpGuides.content.first-generation.s1.body": "前往“创作”。请先登录或创建账户；新账户确认邮箱后可一次性获得 10 免费积分。",
  "helpGuides.content.first-generation.s1.title": "打开工作室",
  "helpGuides.content.first-generation.s2.body": "右侧列表显示每个模型及其积分价格。图像、视频和音频模型都从同一个余额中扣费。",
  "helpGuides.content.first-generation.s2.title": "选择模型",
  "helpGuides.content.first-generation.s3.body": "描述您想看到的内容。生成视频时，请说明什么在动以及镜头如何运动。",
  "helpGuides.content.first-generation.s3.title": "写下提示词",
  "helpGuides.content.first-generation.s4.body": "总价显示在 生成 按钮上方，按下之前就能看到。10 秒的片段费用是 5 秒片段的两倍，选择多张图像则价格按数量成倍增加。",
  "helpGuides.content.first-generation.s4.title": "确认费用",
  "helpGuides.content.first-generation.s5.body": "积分在您按下 生成 时扣除。如果生成失败，积分会自动退回您的余额。",
  "helpGuides.content.first-generation.s5.title": "生成",
  "helpGuides.content.first-generation.summary": "选择模型，查看价格，开始生成。",
  "helpGuides.content.first-generation.title": "生成您的第一张图像或视频",
  "helpGuides.content.library.l1": "打开素材库",
  "helpGuides.content.library.s1.body": "每次生成都会列出，包括失败的，因此您可以看到哪些已退款。",
  "helpGuides.content.library.s1.title": "打开素材库",
  "helpGuides.content.library.s2.body": "按状态和类型（图像、视频、音频）筛选，并可在网格和列表视图之间切换。",
  "helpGuides.content.library.s2.title": "筛选",
  "helpGuides.content.library.s3.body": "卡片上的星标会将其加入 Favourites。Favourites 只保存在您加星标时所用的浏览器中。",
  "helpGuides.content.library.s3.title": "给喜欢的内容加星标",
  "helpGuides.content.library.s4.body": "生成的文件不会永久保存。每张卡片都会注明文件的保留时长，请在到期前下载您需要的内容。",
  "helpGuides.content.library.s4.title": "下载您想保留的内容",
  "helpGuides.content.library.summary": "在素材库中筛选、加星标和下载。",
  "helpGuides.content.library.title": "查找并保存您生成的内容",
  "helpGuides.content.templates.l1": "浏览模板",
  "helpGuides.content.templates.s1.body": "按类别筛选。每张卡片都会显示它所用的模型和价格。",
  "helpGuides.content.templates.s1.title": "浏览模板",
  "helpGuides.content.templates.s2.body": "模板页面会显示完整的提示词、费用，以及（如果模型需要）您必须上传的内容。",
  "helpGuides.content.templates.s2.title": "打开一个模板",
  "helpGuides.content.templates.s3.body": "“使用模板”会打开工作室，并填入提示词、模型和画面比例。按下“生成”前不会扣费。",
  "helpGuides.content.templates.s3.title": "使用模板",
  "helpGuides.content.templates.s4.body": "生成前可以编辑提示词。模板只是起点，不是固定配方。",
  "helpGuides.content.templates.s4.title": "改成您的风格",
  "helpGuides.content.templates.summary": "一键套用现成的提示词、模型和画面比例。",
  "helpGuides.content.templates.title": "从模板开始",
  "helpGuides.content.your-own-files.l1": "查看工具",
  "helpGuides.content.your-own-files.l2": "可接受使用",
  "helpGuides.content.your-own-files.s1.body": "Tools 页面列出所有以您自己的文件为起点的模型，以及它们的要求和费用。",
  "helpGuides.content.your-own-files.s1.title": "选择工具",
  "helpGuides.content.your-own-files.s2.body": "图像可以是 PNG、JPEG 或 WebP，最大 20 MB。视频为 MP4，最大 100 MB。语音为 MP3 或 WAV，最大 20 MB。",
  "helpGuides.content.your-own-files.s2.title": "添加您的文件",
  "helpGuides.content.your-own-files.s3.body": "对于图像，可以用 从素材库选择 选择您已生成的图像，无需重新上传。",
  "helpGuides.content.your-own-files.s3.title": "或者复用已有结果",
  "helpGuides.content.your-own-files.s4.body": "勾选声明框，表示该文件归您所有，或已获得文件中所有可辨认人物的许可。该声明会与本次生成一并记录。",
  "helpGuides.content.your-own-files.s4.title": "确认您有权使用",
  "helpGuides.content.your-own-files.s5.body": "价格以及失败时的退款与其他任何生成完全相同。",
  "helpGuides.content.your-own-files.s5.title": "生成",
  "helpGuides.content.your-own-files.summary": "对您已有的文件进行放大、抠图、扩展、编辑、动画化或口型同步。",
  "helpGuides.content.your-own-files.title": "处理您自己的图像或视频",
  "helpGuides.lead": "关于创作、保存作品和使用积分的简短指南。",
  "helpGuides.links": "接下来去哪里",
  "helpGuides.mobile.credits.buying": "在“积分”页面通过 App Store 或 Google Play 购买积分包。确认前商店会显示价格。购买的积分永不过期。",
  "helpGuides.mobile.firstGeneration.model": "在“创作”中选择模型。每个模型都会显示积分价格。图像、视频和音频模型共用同一余额。",
  "helpGuides.mobile.library.favourites": "点击卡片上的星标可加入收藏。收藏按账户保存在此手机上，不会与网站或其他设备同步。",
